import { api, clearToken, Incident, IncidentRecommendation, setToken, token } from './api'

const nav = [
  { to: '/', label: 'Overview', icon: LayoutDashboard, end: true },
  { to: '/incidents', label: 'Payment incidents', icon: Activity },
  { to: '/treasury', label: 'Treasury planning', icon: WalletCards },
  { to: '/approvals', label: 'Approval center', icon: ShieldCheck },
  { to: '/audit', label: 'Audit trail', icon: FileClock },
]
function App() {
  const [auth, setAuth] = useState(!!token())
  const [mobileOpen, setMobileOpen] = useState(false)
  const [showCreate, setShowCreate] = useState(false)
  const navigate = useNavigate()
  if (!auth) return <Login onLogin={() => setAuth(true)} />
  return <div className="shell">
    <aside className={`sidebar ${mobileOpen ? 'sidebar-open' : ''}`}>
      <div className="brand"><div className="brand-mark"><span/><span/><span/></div><div><b>TreasuryPilot</b><small>FINANCE OPERATIONS</small></div><button className="icon-button mobile-close" onClick={() => setMobileOpen(false)} aria-label="Close navigation"><X size={18}/></button></div>
      <div className="workspace"><div className="workspace-icon">T</div><div><b>Operator workspace</b><small>Airwallex sandbox</small></div></div>
      <div className="nav-label">WORKSPACE</div><nav>{nav.map(item => <NavLink key={item.to} to={item.to} end={item.end} onClick={() => setMobileOpen(false)} className={({isActive}) => `nav-item ${isActive ? 'active' : ''}`}><item.icon size={17}/><span>{item.label}</span></NavLink>)}</nav>
      <div className="sidebar-bottom"><NavLink to="/settings" className="nav-item"><Settings2 size={17}/><span>Settings</span></NavLink><div className="help-card"><div className="help-icon"><CircleHelp size={17}/></div><b>Need a hand?</b><p>Visit the operations guide for help with your workspace.</p><a href="https://airwallexdev.com/guide" target="_blank" rel="noreferrer">Open guide <ChevronRight size={13}/></a></div><div className="user-row"><div className="avatar">OP</div><div className="user-info"><b>Finance operator</b><small>Operator access</small></div><button className="icon-button" aria-label="Sign out" onClick={() => {clearToken();setAuth(false);navigate('/')}}><LogOut size={16}/></button></div></div>
    </aside>
    {mobileOpen && <button className="mobile-scrim" onClick={() => setMobileOpen(false)} aria-label="Close menu"/>}
    <main className="main"><header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMobileOpen(true)} aria-label="Open menu"><Menu size={20}/></button><div className="breadcrumbs">TreasuryPilot <span>/</span> <b>Operations</b></div><div className="top-actions"><div className="env-pill"><i/> Sandbox environment</div><div className="avatar small-avatar" aria-label="Finance operator">OP</div></div></header>
      <div className="content"><Routes><Route path="/" element={<Overview onCreate={() => setShowCreate(true)}/>}/><Route path="/incidents" element={<Incidents onCreate={() => setShowCreate(true)}/>}/><Route path="/incidents/:id" element={<IncidentDetail/>}/><Route path="/treasury" element={<Treasury/>}/><Route path="/approvals" element={<ApprovalCenter/>}/><Route path="/audit" element={<Audit/>}/><Route path="/settings" element={<TreasurySettings/>}/></Routes></div>
    </main>{showCreate && <CreateIncident onClose={() => setShowCreate(false)} onCreated={id => {setShowCreate(false);navigate(`/incidents/${id}`)}}/>}
  </div>
}
function Login({onLogin}:{onLogin:()=>void}) { const [value,setValue]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false); async function submit(e:FormEvent){e.preventDefault();setBusy(true);setToken(value);try{await api('/integrations/airwallex/status');onLogin()}catch(err){clearToken();setError(err instanceof Error?err.message:'Could not sign in')}finally{setBusy(false)}}return <div className="login-screen"><div className="login-card"><div className="brand login-brand"><div className="brand-mark"><span/><span/><span/></div><div><b>TreasuryPilot</b><small>FINANCE OPERATIONS</small></div></div><div className="login-icon"><LockKeyhole size={21}/></div><p className="eyebrow">SECURE OPERATOR ACCESS</p><h1>Welcome back</h1><p className="muted">Sign in with your workspace operator token to continue.</p><form onSubmit={submit}><label htmlFor="token">Operator token</label><input id="token" type="password" autoComplete="current-password" value={value} onChange={e=>setValue(e.target.value)} placeholder="Enter your API access token" required/><button className="primary full" disabled={busy}>{busy?'Checking access…':'Continue'} <ChevronRight size={16}/></button>{error&&<p className="error-text">{error}</p>}</form><div className="login-foot"><LockKeyhole size={13}/> Token is held in this browser session only.</div></div><div className="login-caption">Treasury confidence, built into every decision.</div></div>}
function PageHead({kicker,title,description,action}:{kicker:string,title:string,description:string,action?:React.ReactNode}){return <div className="page-head"><div><div className="eyebrow">{kicker}</div><h1>{title}</h1><p>{description}</p></div>{action}</div>}
function StatusPill({children,tone='neutral'}:{children:React.ReactNode,tone?:string}) {return <span className={`status-pill ${tone}`}><i/>{children}</span>}
type BalanceSnapshot = { captured_at: string; balances: { account_type: string | null; currency: string; available_amount: string; captured_at: string }[] }
type ObligationRecord = { id:number; supplier:string; amount:string; currency:string; due_at:string|null; priority:string; status:string; source:string; simulated:boolean }
type TreasuryPolicy = { currency:string; reserve_floor:string; approval_threshold:string; priority_order:string[]; version:number }
type AuditRecord = { actor:string; timestamp:string; event_type:string; incident_id:string|null; external_transfer_id:string|null; new_state:string|null; policy_version:number|null; approval_reference:string|null }
type ApprovalRecord = { id:string; action:string; incident_id:string; original_transfer_id:string; operation_id:string|null; operation_status:string|null; counterparty:string; amount:string; currency:string; status:string; expires_at:string; requested_by:string|null; approved_by:string|null; approved_at:string|null; policy_version:number|null }
type LivePlan = { id:string; source:string; status:string; data_as_of:string; assumptions:string[]; currency_plans:{currency:string;status:string;available_amount:string|null;reserve_floor:string|null;approval_threshold:string|null;policy_version:number|null;reasons:string[];entries:{obligation_id:number;supplier:string;amount:string;currency:string;priority:string;source:string;action:string;approval_required:boolean;projected_balance_after_payment:string|null;reasons:string[]}[]}[] }
type DemoRecoveryStep = { name:string; source:string; [key:string]:any }
type DemoRecoveryScenario = { scenario_id:string; simulated:boolean; source:string; external_api_called:boolean; persisted_to_incidents:boolean; captured_at:string; disclosure:string; steps:DemoRecoveryStep[]; assumptions:string[] }
function groupedDecimal(value:string) {
  const match=value.trim().match(/^(-?)(\d+)(?:\.(\d+))?$/)
  if(!match)return value
  const fraction=(match[3]||'').replace(/0+$/,'')
  const integer=match[2].replace(/\B(?=(\d{3})+(?!\d))/g,',')
  return `${match[1]}${integer}${fraction?`.${fraction}`:''}`
}
function formatMoney(value:string,currency:string) {
  return `${currency} ${groupedDecimal(value)}`
}
function sumDecimalStrings(values:string[]) {
  const parsed=values.map(value=>value.trim().match(/^(-?)(\d+)(?:\.(\d+))?$/))
  if(parsed.some(value=>!value))return 'Unavailable'
  const parts=parsed as RegExpMatchArray[]
  const scale=Math.max(0,...parts.map(part=>(part[3]||'').length))
  const factor=10n**BigInt(scale)
  const total=parts.reduce((sum,part)=>{
    const fraction=(part[3]||'').padEnd(scale,'0')
    const magnitude=BigInt(part[2])*factor+BigInt(fraction||'0')
    return sum+(part[1]==='-'?-magnitude:magnitude)
  },0n)
  const negative=total<0n
  const magnitude=negative?-total:total
  const whole=(magnitude/factor).toString()
  const fraction=scale?(magnitude%factor).toString().padStart(scale,'0').replace(/0+$/,''):''
  return groupedDecimal(`${negative?'-':''}${whole}${fraction?`.${fraction}`:''}`)
}
function Overview({onCreate}:{onCreate:()=>void}) {
  const {data:integration} = useQuery<{configured:boolean;status:string;note:string}>({queryKey:['integration'],queryFn:()=>api('/integrations/airwallex/status')})
  const credentialsSet = integration?.configured === true
  const balanceQuery = useQuery<BalanceSnapshot>({queryKey:['balances'],queryFn:()=>api<BalanceSnapshot>('/treasury/balances'),enabled:credentialsSet})
  const incidentsQuery = useQuery({queryKey:['incidents'],queryFn:()=>api<Incident[]>('/incidents')})
  const obligationsQuery = useQuery({queryKey:['obligations'],queryFn:()=>api<ObligationRecord[]>('/treasury/obligations')})
  const policiesQuery = useQuery({queryKey:['treasury-policies'],queryFn:()=>api<TreasuryPolicy[]>('/treasury/policies')})
  const auditQuery = useQuery({queryKey:['audit'],queryFn:()=>api<AuditRecord[]>('/audit?limit=20')})
  const approvalsQuery = useQuery({queryKey:['approvals'],queryFn:()=>api<ApprovalRecord[]>('/approvals')})
  const incidents = incidentsQuery.data || []
  const obligations = obligationsQuery.data || []
  const policies = policiesQuery.data || []
  const auditEvents = auditQuery.data || []
  const approvals = approvalsQuery.data || []
  const balances = balanceQuery.data?.balances || []
  const refreshed = balanceQuery.data?.captured_at
  const now = Date.now()
  const dueSoon = obligations.filter(item => item.due_at && new Date(item.due_at).getTime() >= now && new Date(item.due_at).getTime() <= now + 7 * 24 * 60 * 60 * 1000)
  const overdue = obligations.filter(item => item.due_at && new Date(item.due_at).getTime() < now)
  const formatTotals = (rows:ObligationRecord[]) => {
    const totals = rows.reduce<Record<string,string[]>>((all,item) => ({...all,[item.currency]:[...(all[item.currency]||[]),item.amount]}),{})
    const summary = Object.entries(totals).sort(([a],[b])=>a.localeCompare(b)).map(([currency,amounts])=>`${currency} ${sumDecimalStrings(amounts)}`)
    return summary.length ? summary.join(' · ') : 'No open obligations'
  }
  const missingPolicies = [...new Set(obligations.map(item=>item.currency))].filter(currency=>!policies.some(policy=>policy.currency===currency))
  const criticalAlerts = [
    ...(credentialsSet && balanceQuery.error ? ['Airwallex balance read failed; live cash is unavailable.'] : []),
    ...(obligationsQuery.error ? ['Open obligations could not be loaded; planning cannot be evaluated.'] : []),
    ...(policiesQuery.error ? ['Reserve policies could not be loaded; planning must remain blocked.'] : []),
    ...(approvalsQuery.error ? ['Approval records could not be loaded; authorization state is unavailable.'] : []),
    ...(overdue.length ? [`${overdue.length} operator-entered obligation${overdue.length===1?' is':'s are'} past due.`] : []),
    ...missingPolicies.map(currency=>`No ${currency} reserve policy is configured for open obligations.`),
  ]
  return <>
    <PageHead kicker="PAYMENT OPERATIONS" title="Good morning, operator" description="Here’s the latest across your treasury operations." action={<button className="primary" onClick={onCreate}><Plus size={16}/> New incident</button>}/>
    <div className="alert-banner"><div className="alert-glyph"><ShieldCheck size={17}/></div><div><b>Financial actions stay protected</b><p>Transfers are never retried automatically. Every recovery requires verified failure evidence, fresh balances, and policy approval.</p></div><ChevronRight size={16} className="alert-arrow"/></div>
    <div className="section-line"><h2>Operations overview</h2><span>{refreshed ? `Balances refreshed ${new Date(refreshed).toLocaleString()}` : 'No successful balance refresh'}</span></div>
    <div className="stats-grid overview-stats"><StatCard label="Available balances" value={balances.length ? `${balances.length} currencies` : 'Unavailable'} hint={balances.length ? balances.map(item=>`${item.currency} ${groupedDecimal(item.available_amount)}`).join(' · ') : credentialsSet ? 'Sandbox read not verified' : 'Airwallex is not connected'} icon={<WalletCards/>} tone="green"/><StatCard label="Open obligations" value={obligationsQuery.isPending||obligationsQuery.error?'Unavailable':`${obligations.length} records`} hint={obligationsQuery.error?'Obligation data unavailable':formatTotals(obligations)} icon={<ArrowUpRight/>}/><StatCard label="Due in 7 days" value={obligationsQuery.isPending||obligationsQuery.error?'Unavailable':`${dueSoon.length} ${dueSoon.length===1?'obligation':'obligations'}`} hint={obligationsQuery.error?'Due-date data unavailable':formatTotals(dueSoon)} icon={<Clock3/>} tone={dueSoon.length?'orange':''}/><StatCard label="Payment incidents" value={incidentsQuery.isPending||incidentsQuery.error?'Unavailable':String(incidents.length).padStart(2,'0')} hint={incidentsQuery.error?'Incident data unavailable':incidents.length?'Needs attention':'No open incidents'} icon={<Activity/>} tone="orange"/><StatCard label="Pending approvals" value={approvalsQuery.isPending||approvalsQuery.error?'Unavailable':String(approvals.filter(item=>item.status==='PENDING'&&new Date(item.expires_at).getTime()>now).length)} hint={approvalsQuery.error?'Approval state unavailable':approvals.length?`${approvals.length} saved action-bound records`:'No persisted approval requests'} icon={<ShieldCheck/>}/><StatCard label="Reserve policies" value={policiesQuery.isPending||policiesQuery.error?'Unavailable':`${policies.length} configured`} hint={policiesQuery.error?'Policy data unavailable':missingPolicies.length?`Missing for ${missingPolicies.join(', ')}`:'Configured currencies have saved policy'} icon={<ShieldCheck/>} tone={missingPolicies.length?'orange':'green'}/></div>
    <div className="overview-grid"><section className="panel integration-panel"><div className="panel-heading"><div><div className="eyebrow">CONNECTION</div><h2>Airwallex account</h2></div><StatusPill tone={balances.length?'success':'warning'}>{balances.length?'Read verified':credentialsSet?'Credentials set · not verified':'Not connected'}</StatusPill></div>
    <div className="integration-content"><div className={`integration-symbol ${balances.length?'connected':''}`}><CreditCard size={23}/></div><div><b>{balances.length?'Read-only balance retrieval succeeded':credentialsSet?'Credentials configured; read-only check pending':'Sandbox credentials required'}</b><p>{balanceQuery.error instanceof Error ? balanceQuery.error.message : integration?.note || 'Checking backend integration status…'}</p></div></div>
    {balances.length ? balances.map(item=><div className="integration-foot" key={`${item.account_type}-${item.currency}`}><span>{item.currency} available</span><b>{formatMoney(item.available_amount,item.currency)}</b></div>) : <><div className="integration-foot"><span><i className="dot"/> Environment</span><b>Sandbox</b></div><div className="integration-foot"><span><Clock3 size={13}/> Last balance refresh</span><b>Not available</b></div></>}</section>
    <section className="panel recent-panel"><div className="panel-heading"><div><div className="eyebrow">INBOX</div><h2>Recent incidents</h2></div><NavLink to="/incidents" className="text-link">View all <ChevronRight size={14}/></NavLink></div>{incidentsQuery.isPending ? <div className="empty-state"><b>Loading incidents…</b></div> : incidentsQuery.error ? <div className="empty-state"><b>Incident data unavailable</b><p>{String(incidentsQuery.error)}</p></div> : incidents.length ? <div className="incident-list">{incidents.slice(0,3).map(i=><IncidentRow key={i.id} incident={i}/>)}</div> : <div className="empty-state"><div className="empty-icon"><Activity size={18}/></div><b>No open incidents</b><p>Payment concerns will show here for investigation.</p><button className="secondary small" onClick={onCreate}><Plus size={14}/> Create incident</button></div>}</section></div>
    <div className="overview-grid overview-lower-grid"><section className="panel recent-panel"><div className="panel-heading"><div><div className="eyebrow">AUDIT</div><h2>Recent financial operations</h2></div><NavLink to="/audit" className="text-link">Full audit <ChevronRight size={14}/></NavLink></div>{auditQuery.isPending?<div className="empty-state">Loading recent events…</div>:auditQuery.error?<div className="empty-state error-text">Audit history unavailable: {String(auditQuery.error)}</div>:auditEvents.length?<div className="overview-operations">{auditEvents.slice(0,5).map((event,index)=><div className="overview-operation" key={`${event.timestamp}-${index}`}><div><b>{event.event_type.replaceAll('_',' ').toLowerCase()}</b><small>{event.incident_id?`Incident ${event.incident_id.slice(0,8)}`:'Workspace event'} · {new Date(event.timestamp).toLocaleString()}</small></div><StatusPill>{event.new_state||'recorded'}</StatusPill></div>)}</div>:<div className="empty-state"><b>No recorded operations yet</b><p>Incident decisions and policy changes will appear here.</p></div>}</section><section className="panel recent-panel"><div className="panel-heading"><div><div className="eyebrow">POLICY MONITOR</div><h2>Critical alerts</h2></div><StatusPill tone={criticalAlerts.length?'warning':'success'}>{criticalAlerts.length?`${criticalAlerts.length} open`:'No critical alerts'}</StatusPill></div>{criticalAlerts.length?<div className="overview-alerts">{criticalAlerts.map(alert=><p key={alert}><ShieldCheck size={15}/>{alert}</p>)}</div>:<div className="empty-state"><b>No current reserve-policy alerts</b><p>Alerts are based on saved local policies and operator-entered obligations.</p></div>}</section></div>
    <div className="bottom-note"><span><ShieldCheck size={15}/></span><p><b>Good decisions start with good evidence.</b> Supplier messages are treated as claims until verified against transfer records.</p></div>
  </>
}
function StatCard({label,value,hint,icon,tone=''}:{label:string,value:string,hint:string,icon:React.ReactNode,tone?:string}){return <div className="stat-card"><div className="stat-top"><span>{label}</span><div className={`stat-icon ${tone}`}>{icon}</div></div><strong>{value}</strong><small>{hint}</small></div>}
function Incidents({onCreate}:{onCreate:()=>void}){const {data=[],isLoading,error}=useQuery({queryKey:['incidents'],queryFn:()=>api<Incident[]>('/incidents')});const [query,setQuery]=useState('');const rows=data.filter(x=>`${x.supplier} ${x.original_transfer_id} ${x.state}`.toLowerCase().includes(query.toLowerCase()));return <><PageHead kicker="PAYMENT OPERATIONS" title="Payment incidents" description="Investigate uncertain supplier transfers and keep recovery actions safe." action={<button className="primary" onClick={onCreate}><Plus size={16}/> New incident</button>}/><div className="table-toolbar"><div className="search-box"><Search size={16}/><input aria-label="Filter incidents" placeholder="Search supplier or transfer ID" value={query} onChange={e=>setQuery(e.target.value)}/></div><span className="muted small-text">{data.length} incidents</span></div><div className="panel table-wrap"><table><thead><tr><th>SUPPLIER</th><th>TRANSFER</th><th>AMOUNT</th><th>VERIFIED STATUS</th><th>INVESTIGATION</th><th>CREATED</th><th/></tr></thead><tbody>{isLoading?<tr><td colSpan={7} className="table-message">Loading incidents…</td></tr>:error?<tr><td colSpan={7} className="table-message error-text">{String(error)}</td></tr>:rows.length?rows.map(i=><IncidentTableRow key={i.id} incident={i}/>):<tr><td colSpan={7}><div className="empty-state table-empty"><div className="empty-icon"><Activity size={18}/></div><b>No incidents found</b><p>Create an incident to start an evidence-based investigation.</p><button className="secondary small" onClick={onCreate}><Plus size={14}/> Create incident</button></div></td></tr>}</tbody></table></div></>}
function IncidentTableRow({incident:i}:{incident:Incident}){return <tr className="click-row" onClick={()=>location.assign(`/incidents/${i.id}`)}><td><div className="supplier-cell"><div className="supplier-avatar">{i.supplier.charAt(0).toUpperCase()}</div><b>{i.supplier}</b></div></td><td><code>{i.original_transfer_id}</code></td><td><b>{formatMoney(i.amount,i.currency)}</b></td><td><StatusPill tone={i.external_status?'warning':'neutral'}>{i.external_status||'Not retrieved'}</StatusPill></td><td><StatusPill tone="warning">{i.state.replaceAll('_',' ').toLowerCase()}</StatusPill></td><td>{new Date(i.created_at).toLocaleDateString()}</td><td><ChevronRight size={16}/></td></tr>}
function IncidentRow({incident:i}:{incident:Incident}){return <NavLink to={`/incidents/${i.id}`} className="recent-item"><div className="supplier-avatar">{i.supplier.charAt(0).toUpperCase()}</div><div className="recent-copy"><b>{i.supplier}</b><small>{i.original_transfer_id} · {i.state.replaceAll('_',' ').toLowerCase()}</small></div><div className="recent-amount">{formatMoney(i.amount,i.currency)}<ChevronRight size={14}/></div></NavLink>}
function CreateIncident({onClose,onCreated}:{onClose:()=>void,onCreated:(id:string)=>void}){const [form,setForm]=useState({supplier:'',original_transfer_id:'',amount:'',currency:'USD',supplier_claim:''});const [error,setError]=useState('');const [busy,setBusy]=useState(false);async function submit(e:FormEvent){e.preventDefault();setBusy(true);setError('');try{const result=await api<Incident>('/incidents',{method:'POST',body:JSON.stringify(form)});onCreated(result.id)}catch(e){setError(e instanceof Error?e.message:'Could not create incident')}finally{setBusy(false)}}return <div className="modal-scrim" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="create-incident-title"><div className="modal-head"><div><div className="eyebrow">PAYMENT OPERATIONS</div><h2 id="create-incident-title">New payment incident</h2></div><button className="icon-button" aria-label="Close" onClick={onClose}><X size={18}/></button></div><p className="muted">Supplier information is recorded as a claim until the original transfer is retrieved.</p><form onSubmit={submit}><label>Supplier name<input required maxLength={200} value={form.supplier} onChange={e=>setForm({...form,supplier:e.target.value})} placeholder="e.g. Acme Components"/></label><label>Original transfer ID<input required value={form.original_transfer_id} onChange={e=>setForm({...form,original_transfer_id:e.target.value})} placeholder="Airwallex transfer identifier"/></label><div className="form-row"><label>Amount<input required type="number" min="0.01" step="0.0001" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})} placeholder="0.00"/></label><label>Currency<select value={form.currency} onChange={e=>setForm({...form,currency:e.target.value})}><option>USD</option><option>EUR</option><option>GBP</option><option>SGD</option><option>AUD</option></select></label></div><label>Supplier's message<textarea required maxLength={4000} rows={3} value={form.supplier_claim} onChange={e=>setForm({...form,supplier_claim:e.target.value})} placeholder="Paste the reported payment concern…"/></label><div className="claim-note"><ShieldCheck size={15}/> This text is treated as an unverified claim, not an instruction.</div>{error&&<p className="error-text">{error}</p>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy}>{busy?'Creating…':'Create incident'} <ChevronRight size={15}/></button></div></form></div></div>}
function CreateObligation({onClose,onCreated}:{onClose:()=>void,onCreated:()=>void}){
  const [form,setForm]=useState({supplier:'',amount:'',currency:'USD',priority:'NORMAL',due_at:''})
  const [error,setError]=useState('')
  const [busy,setBusy]=useState(false)
  async function submit(e:FormEvent){
    e.preventDefault();setBusy(true);setError('')
    const body={...form,due_at:form.due_at?new Date(form.due_at).toISOString():null}
    try{await api('/treasury/obligations',{method:'POST',body:JSON.stringify(body)});onCreated()}
    catch(err){setError(err instanceof Error?err.message:'Could not record obligation')}
    finally{setBusy(false)}
  }
  return <div className="modal-scrim" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="create-obligation-title">
    <div className="modal-head"><div><div className="eyebrow">TREASURY PLANNING</div><h2 id="create-obligation-title">Record supplier obligation</h2></div><button className="icon-button" aria-label="Close" onClick={onClose}><X size={18}/></button></div>
    <p className="muted">This creates an operator-entered planning record. It does not verify a payable or start a transfer.</p>
    <form onSubmit={submit}><label>Supplier name<input required maxLength={200} value={form.supplier} onChange={e=>setForm({...form,supplier:e.target.value})}/></label>
      <div className="form-row"><label>Amount<input required type="number" min="0.0001" step="0.0001" value={form.amount} onChange={e=>setForm({...form,amount:e.target.value})}/></label><label>Currency<select value={form.currency} onChange={e=>setForm({...form,currency:e.target.value})}><option>USD</option><option>EUR</option><option>GBP</option><option>SGD</option><option>AUD</option></select></label></div>
      <div className="form-row"><label>Priority<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}><option>CRITICAL</option><option>HIGH</option><option>NORMAL</option><option>LOW</option></select></label><label>Due date<input type="date" value={form.due_at} onChange={e=>setForm({...form,due_at:e.target.value})}/></label></div>
      {error&&<p role="alert" className="error-text">{error}</p>}<div className="modal-actions"><button type="button" className="secondary" onClick={onClose}>Cancel</button><button className="primary" disabled={busy}>{busy?'Saving…':'Record obligation'} <ChevronRight size={15}/></button></div>
    </form></div></div>
}
function IncidentDetail(){
  const {id:incidentId=''} = useParams()
  const {data:i,isLoading,error,refetch} = useQuery({queryKey:['incident',incidentId],queryFn:()=>api<Incident>(`/incidents/${incidentId}`)})
  const [result,setResult] = useState<any>(null)
  const [busy,setBusy] = useState(false)
  const [evaluation,setEvaluation] = useState<any>(null)
  const [recommendation,setRecommendation] = useState<IncidentRecommendation|null>(null)
  const [beneficiary,setBeneficiary] = useState<any>(null)
  async function investigate(){setBusy(true);try{setResult(await api(`/incidents/${incidentId}/investigate`,{method:'POST'}));await refetch()}catch(e){setResult({note:String(e)})}finally{setBusy(false)}}
  async function evaluate(){setBusy(true);try{setEvaluation(await api(`/incidents/${incidentId}/evaluate-recovery`,{method:'POST'}))}catch(e){setEvaluation({reasons:[String(e)]})}finally{setBusy(false)}}
  async function interpret(){setBusy(true);try{setRecommendation(await api<IncidentRecommendation>(`/incidents/${incidentId}/recommendation`,{method:'POST'}))}catch(e){setRecommendation({incident_id:incidentId,verified_facts:{},unverified_claims:[],ai_interpretation:null,ai_status:'unavailable',proposed_action:'INVESTIGATE',next_step:String(e),financial_action_authorized:false,note:'Recommendation could not be loaded.'})}finally{setBusy(false)}}
  async function refreshBeneficiary(){setBusy(true);try{setBeneficiary(await api(`/incidents/${incidentId}/refresh-beneficiary`,{method:'POST'}))}catch(e){setBeneficiary({error:String(e)})}finally{setBusy(false)}}
  if(isLoading)return <p>Loading incident…</p>
  if(error||!i)return <div className="error-card">{String(error||'Incident not found')}</div>
  const evidence = [...(i.evidence||[])].reverse()
  const verified = evidence.find(item=>item.source==='airwallex')
  const transfer = verified?.payload||{}
  return <><div className="back-link"><NavLink to="/incidents">← Payment incidents</NavLink></div>
    <PageHead kicker="INCIDENT DETAIL" title={i.supplier} description={`Incident ${i.id.slice(0,8)} · Opened ${new Date(i.created_at).toLocaleString()}`}/>
    <div className="detail-grid"><div className="panel detail-primary">
      <div className="panel-heading"><div><div className="eyebrow">ORIGINAL TRANSFER</div><h2>{i.original_transfer_id}</h2></div><StatusPill tone={verified?'warning':'neutral'}>{i.external_status||'Not retrieved'}</StatusPill></div>
      <div className="amount-hero">{formatMoney(i.amount,i.currency)}<span>{i.currency}</span></div>
      <div className="detail-lines"><div><span>Supplier-provided information</span><p>{i.supplier_claim}</p><StatusPill>Unverified claim</StatusPill></div>
      <div><span>Verified Airwallex evidence</span>{verified ? <><p>Transfer status: <b>{String(transfer.status||i.external_status)}</b>{transfer.transfer_amount!==undefined&&` · Amount: ${transfer.transfer_amount} ${transfer.transfer_currency||''}`}</p><StatusPill tone="success">Retrieved from Airwallex</StatusPill><p className="evidence-time">Evidence captured {new Date(verified.captured_at).toLocaleString()}</p></> : <><p>No transfer evidence has been retrieved.</p><StatusPill tone="warning">Unverified</StatusPill></>}</div></div>
      <div className="button-row"><button className="secondary" disabled={busy} onClick={investigate}><Search size={15}/>{busy?'Checking…':'Investigate transfer'}</button><button className="primary" disabled={busy} onClick={evaluate}><ShieldCheck size={15}/>Evaluate recovery</button></div>
      <div className="button-row"><button className="secondary" disabled={busy||!verified?.payload?.beneficiary_id} title={!verified?.payload?.beneficiary_id?'Investigate the transfer first to verify its saved beneficiary':undefined} onClick={refreshBeneficiary}><CreditCard size={15}/>{busy?'Checking…':'Refresh saved beneficiary'}</button></div>
      <div className="button-row"><button className="secondary" disabled={busy} onClick={interpret}><Activity size={15}/>{busy?'Preparing…':'Generate AI interpretation'}</button></div>
      {result&&<div className="result-note"><b>Investigation result</b><p>{result.note}</p><small>Verified facts: {result.verified_facts?.length||0} · State: {result.state}</small></div>}
      {evaluation&&<div className={`result-note ${evaluation.eligible?'':'blocked'}`}><b>{evaluation.eligible?'Eligible for review':'Recovery blocked'}</b><ul>{evaluation.reasons?.map((x:string)=><li key={x}>{x}</li>)}</ul></div>}
      {recommendation&&<div className="result-note"><b>{recommendation.ai_interpretation?'AI interpretation':'AI unavailable · deterministic next step'}</b>{recommendation.ai_interpretation&&<><p>{recommendation.ai_interpretation.summary}</p>{recommendation.ai_interpretation.uncertainty_flags.length>0&&<ul>{recommendation.ai_interpretation.uncertainty_flags.map((flag,index)=><li key={`${flag}-${index}`}>{flag}</li>)}</ul>}</>}<p>Next step: {recommendation.next_step}</p><small>{recommendation.note} No financial action is authorized.</small></div>}
      {beneficiary?.beneficiary&&<div className="result-note"><b>Saved beneficiary · retrieved from Airwallex</b><p>{beneficiary.beneficiary.nickname||beneficiary.beneficiary.id} · {beneficiary.beneficiary.entity_type||'Entity type unavailable'} · {beneficiary.beneficiary.beneficiary_type||'Beneficiary type unavailable'}</p><small>{beneficiary.beneficiary.bank_country_code||'Bank country unavailable'} · {beneficiary.beneficiary.account_currency||'Account currency unavailable'} · {beneficiary.beneficiary.transfer_methods.join(', ')}. {beneficiary.note}</small></div>}
      {beneficiary?.error&&<div className="error-card" role="alert">{beneficiary.error}</div>}
    </div><div className="detail-side"><section className="panel side-card"><div className="eyebrow">INVESTIGATION</div><h3>Current classification</h3><StatusPill tone="warning">{i.state.replaceAll('_',' ').toLowerCase()}</StatusPill><p>Supplier statements and transfer records are displayed as separate evidence types.</p></section><section className="panel side-card"><div className="eyebrow">DUPLICATE RISK</div><h3>Replacement blocked</h3><p>Until a failure is verified and the treasury, fee, reserve, duplicate, and approval checks pass, another payment cannot be started.</p></section><section className="panel side-card"><div className="eyebrow">NEXT STEP</div><h3>{verified?'Refresh transfer evidence':'Retrieve transfer evidence'}</h3><p>{result?.note||'Use the investigation action to retrieve current transfer details from Airwallex.'}</p></section></div></div>
  </>
}
function Treasury(){
  const {data:integration} = useQuery({queryKey:['integration'],queryFn:()=>api<any>('/integrations/airwallex/status')})
  const balancesQuery = useQuery<BalanceSnapshot>({queryKey:['balances'],queryFn:()=>api<BalanceSnapshot>('/treasury/balances'),enabled:integration?.configured===true})
  const obligationsQuery = useQuery<ObligationRecord[]>({queryKey:['obligations'],queryFn:()=>api<ObligationRecord[]>('/treasury/obligations')})
  const [demo,setDemo] = useState<any>(null)
  const [demoError,setDemoError] = useState('')
  const [demoBusy,setDemoBusy] = useState(false)
  const [recoveryDemo,setRecoveryDemo] = useState<DemoRecoveryScenario|null>(null)
  const [recoveryDemoError,setRecoveryDemoError] = useState('')
  const [recoveryDemoBusy,setRecoveryDemoBusy] = useState(false)
  const [livePlan,setLivePlan] = useState<LivePlan|null>(null)
  const [livePlanError,setLivePlanError] = useState('')
  const [livePlanBusy,setLivePlanBusy] = useState(false)
  const [showObligation,setShowObligation] = useState(false)
  const balances = balancesQuery.data?.balances || []
  async function loadDemo(){setDemoBusy(true);setDemoError('');try{setDemo(await api('/demo/treasury-plan'))}catch(error){setDemoError(error instanceof Error?error.message:'Could not load the synthetic planning example')}finally{setDemoBusy(false)}}
  async function runRecoveryDemo(){setRecoveryDemoBusy(true);setRecoveryDemoError('');try{setRecoveryDemo(await api<DemoRecoveryScenario>('/demo/recovery-scenario'))}catch(error){setRecoveryDemoError(error instanceof Error?error.message:'Could not load the synthetic recovery walkthrough')}finally{setRecoveryDemoBusy(false)}}
  async function calculatePlan(){setLivePlanBusy(true);setLivePlanError('');try{setLivePlan(await api<LivePlan>('/treasury/plans',{method:'POST'}))}catch(error){setLivePlanError(error instanceof Error?error.message:'Could not calculate treasury plan')}finally{setLivePlanBusy(false)}}
  return <><PageHead kicker="LIQUIDITY MANAGEMENT" title="Treasury planning" description="Review available cash, obligations, and reserve policies before making a payment decision." action={<div className="treasury-actions"><button className="secondary" onClick={()=>setShowObligation(true)}><Plus size={15}/> Record obligation</button><button className="secondary" onClick={calculatePlan} disabled={!integration?.configured||livePlanBusy} title={!integration?.configured?'Configure Airwallex sandbox credentials first':undefined}>{livePlanBusy?'Calculating…':'Calculate live plan'}</button><button className="secondary" onClick={loadDemo} disabled={demoBusy}>{demoBusy?'Loading example…':'Show simulated plan'}</button><button className="secondary" onClick={runRecoveryDemo} disabled={recoveryDemoBusy}>{recoveryDemoBusy?'Running walkthrough…':'Run recovery demo'}</button></div>}/>
    {balances.length ? <><div className="section-line"><h2>Available by currency</h2><span>As of {new Date(balancesQuery.data!.captured_at).toLocaleString()}</span></div><div className="stats-grid">{balances.map((item)=><StatCard key={`${item.account_type}-${item.currency}`} label={`${item.currency} available`} value={formatMoney(item.available_amount,item.currency)} hint={`Airwallex ${item.account_type||'account'} balance`} icon={<WalletCards/>} tone="green"/>)}</div><div className="alert-banner warning-banner"><div className="alert-glyph"><WalletCards size={17}/></div><div><b>Planning checks are separate from payment authorization</b><p>Reserve policies apply to planning. Transfer fees are not yet known before a write, so eligible actions remain on hold.</p></div></div></> : <><div className="alert-banner warning-banner"><div className="alert-glyph"><WalletCards size={17}/></div><div><b>Live balance data is unavailable</b><p>{balancesQuery.error instanceof Error ? balancesQuery.error.message : 'No live Airwallex balances are shown until sandbox credentials are configured and refreshed.'}</p></div></div><div className="panel empty-state treasury-empty"><div className="empty-icon"><WalletCards size={19}/></div><b>No verified treasury data</b><p>Live planning requires an Airwallex balance read, per-currency reserve policies, and verified fees. No synthetic figures are presented as live cash.</p><NavLink to="/settings" className="secondary small">Treasury policies <ChevronRight size={14}/></NavLink></div></>}
    {livePlanError&&<div role="alert" className="error-card">{livePlanError}</div>}
    {livePlan&&<section className="panel live-plan-panel"><div className="panel-heading"><div><div className="eyebrow">LIVE BALANCE INPUT · {new Date(livePlan.data_as_of).toLocaleString()}</div><h2>Persisted treasury evaluation</h2></div><StatusPill tone={livePlan.status==='PLANNED'?'success':'warning'}>{livePlan.status}</StatusPill></div><p className="muted small-text">Plan {livePlan.id} · source: {livePlan.source}. This is a planning result, not a payment authorization.</p>{livePlan.currency_plans.map(currencyPlan=><div className="live-currency-plan" key={currencyPlan.currency}><div className="section-line"><h3>{currencyPlan.currency} · {currencyPlan.status}</h3><span>{currencyPlan.available_amount===null?'Balance unavailable':`Available ${formatMoney(currencyPlan.available_amount,currencyPlan.currency)}`} {currencyPlan.reserve_floor!==null&&` · Reserve ${formatMoney(currencyPlan.reserve_floor,currencyPlan.currency)}`} {currencyPlan.approval_threshold!==null&&` · Approval threshold ${formatMoney(currencyPlan.approval_threshold,currencyPlan.currency)}`}</span></div>{currencyPlan.reasons.map(reason=><p className="muted small-text" key={reason}>{reason}</p>)}{currencyPlan.entries.length>0&&<div className="table-wrap"><table><thead><tr><th>OBLIGATION</th><th>PRIORITY</th><th>DECISION</th><th>APPROVAL</th><th>PROJECTED BALANCE</th><th>REASONS</th></tr></thead><tbody>{currencyPlan.entries.map(entry=><tr key={entry.obligation_id}><td>{entry.supplier}<small className="table-subtext">{entry.source.replaceAll('_',' ')}</small></td><td>{entry.priority}</td><td><StatusPill tone={entry.action==='PLAN_TO_PAY'?'success':'warning'}>{entry.action}</StatusPill></td><td>{entry.approval_required?'Required':'Not required by threshold'}</td><td>{entry.projected_balance_after_payment===null?'Unavailable':formatMoney(entry.projected_balance_after_payment,entry.currency)}</td><td>{entry.reasons.join(' · ')||'Policy checks passed'}</td></tr>)}</tbody></table></div>}</div>)}<ul className="demo-assumptions">{livePlan.assumptions.map(assumption=><li key={assumption}>{assumption}</li>)}</ul></section>}
    {demoError&&<div role="alert" className="error-card">{demoError}</div>}
    {recoveryDemoError&&<div role="alert" className="error-card">{recoveryDemoError}</div>}
    {recoveryDemo&&<DemoRecoveryPanel scenario={recoveryDemo}/>}
    <section className="panel obligations-panel"><div className="panel-heading"><div><div className="eyebrow">OPERATOR-ENTERED RECORDS</div><h2>Open supplier obligations</h2></div><span className="muted small-text">Not verified against Airwallex</span></div>{obligationsQuery.isPending?<div className="empty-state">Loading obligations…</div>:obligationsQuery.error?<div className="empty-state error-text">{String(obligationsQuery.error)}</div>:obligationsQuery.data?.length?<div className="table-wrap"><table><thead><tr><th>SUPPLIER</th><th>AMOUNT</th><th>PRIORITY</th><th>DUE</th><th>RECORD SOURCE</th></tr></thead><tbody>{obligationsQuery.data.map(item=><tr key={item.id}><td>{item.supplier}</td><td>{formatMoney(item.amount,item.currency)}</td><td>{item.priority}</td><td>{item.due_at?new Date(item.due_at).toLocaleDateString():'Not set'}</td><td>{item.source.replaceAll('_',' ')}</td></tr>)}</tbody></table></div>:<div className="empty-state"><b>No open obligations recorded</b><p>Record obligations supplied by your finance team. These are operator-entered records, not verified payables.</p></div>}</section>
    {demo&&<section className="panel demo-plan-panel"><div className="panel-heading"><div><div className="eyebrow">SIMULATED EXAMPLE · NOT AIRWALLEX DATA</div><h2>Reserve-aware obligation plan</h2></div><StatusPill tone="warning">Simulation</StatusPill></div><div className="alert-banner warning-banner"><div className="alert-glyph"><ShieldCheck size={17}/></div><div><b>Illustrative values only</b><p>${groupedDecimal(demo.available)} available · ${groupedDecimal(demo.reserve_floor)} reserve floor · ${groupedDecimal(demo.remaining_balance)} projected after planned obligations. {demo.fee_assumption}.</p></div></div><div className="table-wrap"><table><thead><tr><th>SUPPLIER</th><th>PRIORITY</th><th>AMOUNT</th><th>PLANNED ACTION</th><th>PROJECTED BALANCE</th></tr></thead><tbody>{demo.entries.map((entry:any)=><tr key={entry.supplier}><td>{entry.supplier}</td><td>{entry.priority}</td><td>{formatMoney(entry.amount,entry.currency)}</td><td><StatusPill tone={entry.action==='PAY'?'success':'warning'}>{entry.action==='PAY'?'Plan to pay':'Defer'}</StatusPill>{entry.reasons.length>0&&<small className="table-subtext">{entry.reasons.join(' · ')}</small>}</td><td>{formatMoney(entry.balance_after_plan,entry.currency)}</td></tr>)}</tbody></table></div><ul className="demo-assumptions">{demo.assumptions.map((assumption:string)=><li key={assumption}>{assumption}</li>)}</ul><p className="muted small-text">This is a planning demonstration only. It creates no obligation record and does not initiate a payment.</p></section>}
    {showObligation&&<CreateObligation onClose={()=>setShowObligation(false)} onCreated={async()=>{setShowObligation(false);await obligationsQuery.refetch()}}/>}
  </>
}
function DemoRecoveryPanel({scenario}:{scenario:DemoRecoveryScenario}){
  const titles:Record<string,string>={investigate_original:'Investigate original transfer',confirm_failure:'Confirm failure evidence',evaluate_treasury:'Evaluate treasury impact',approve_exact_action:'Approve exact action',create_replacement:'Create replacement',verify_replacement:'Verify replacement result'}
  return <section className="panel recovery-demo-panel"><div className="panel-heading"><div><div className="eyebrow">SYNTHETIC END-TO-END WALKTHROUGH</div><h2>Payment incident recovery</h2></div><StatusPill tone="warning">Simulation only</StatusPill></div><div className="alert-banner warning-banner"><div className="alert-glyph"><ShieldCheck size={17}/></div><div><b>No real financial operation occurred</b><p>{scenario.disclosure}</p></div></div><ol className="recovery-demo-timeline">{scenario.steps.map(step=><li key={step.name}><div className="recovery-demo-step-head"><div><b>{titles[step.name]||step.name.replaceAll('_',' ')}</b><small>{step.source.replaceAll('_',' ')}</small></div><StatusPill tone={step.decision==='BLOCK_REPLACEMENT'?'warning':step.status?.startsWith('SIMULATED_')?'neutral':'success'}>{step.decision||step.status||step.transition}</StatusPill></div>{step.reason&&<p>{step.reason}</p>}{step.name==='evaluate_treasury'&&<><p>Available USD {groupedDecimal(step.available)} · reserve USD {groupedDecimal(step.reserve_floor)} · synthetic fee USD {groupedDecimal(step.synthetic_fee)} · projected balance USD {groupedDecimal(step.remaining_balance)}</p><div className="table-wrap"><table><thead><tr><th>OBLIGATION</th><th>PRIORITY</th><th>PLAN</th><th>PROJECTED USD BALANCE</th></tr></thead><tbody>{step.plan.map((entry:any)=><tr key={entry.supplier}><td>{entry.supplier}</td><td>{entry.priority}</td><td>{entry.action==='PAY'?'Plan to pay':'Defer'}</td><td>{groupedDecimal(entry.projected_balance)}</td></tr>)}</tbody></table></div></>}{step.name==='approve_exact_action'&&<p>Approval {step.approval_id} is bound to {step.bound_action.counterparty}, USD {groupedDecimal(step.bound_action.amount)}, original {step.bound_action.original_transfer_id}, evidence {step.bound_action.evidence_version}, policy v{step.bound_action.policy_version}. Hash: <code>{step.action_hash.slice(0,16)}…</code></p>}{step.name==='create_replacement'&&<p>Synthetic request {step.request_id} produced fixture transfer {step.transfer_id}. Airwallex was not called.</p>}{step.name==='verify_replacement'&&<p>This verifies only the fixture state. It is not retrieved Airwallex evidence or proof of supplier receipt.</p>}</li>)}</ol><ul className="demo-assumptions">{scenario.assumptions.map(item=><li key={item}>{item}</li>)}</ul><p className="muted small-text">Scenario {scenario.scenario_id} · Generated {new Date(scenario.captured_at).toLocaleString()} · This scenario does not create an incident or write an audit event.</p></section>
}
function ApprovalCenter(){
  const {data=[],isLoading,error}=useQuery<ApprovalRecord[]>({queryKey:['approvals'],queryFn:()=>api<ApprovalRecord[]>('/approvals')})
  return <>
    <PageHead kicker="GOVERNANCE" title="Approval center" description="Review persisted, action-bound approval records and their current operation state."/>
    <div className="alert-banner warning-banner"><div className="alert-glyph"><ShieldCheck size={17}/></div><div><b>Read-only approval history</b><p>This page does not create approval requests, approve actions, or execute transfers. Live recovery remains unavailable until verified transfer evidence, fresh balances, and fee and reserve checks are connected.</p></div></div>
    <section className="panel audit-panel">
      {isLoading?<div className="empty-state"><b>Loading approval records…</b></div>:error?<div className="empty-state"><b>Approval records unavailable</b><p className="error-text">{String(error)}</p></div>:data.length?<div className="table-wrap"><table><thead><tr><th>ACTION / COUNTERPARTY</th><th>INCIDENT / ORIGINAL</th><th>AMOUNT</th><th>STATUS</th><th>REQUESTED BY</th><th>APPROVED BY</th><th>POLICY</th><th>EXPIRES</th></tr></thead><tbody>{data.map(item=>{const pastExpiry=item.status==='PENDING'&&new Date(item.expires_at).getTime()<=Date.now();const status=pastExpiry?'PENDING · EXPIRED':item.status;const tone=item.status==='APPROVED'?'success':item.status==='PENDING'?'warning':'neutral';return <tr key={item.id}><td><b>{item.action.replaceAll('_',' ')}</b><small className="table-subtext">{item.counterparty} · Approval {item.id.slice(0,8)}</small></td><td><NavLink className="text-link" to={`/incidents/${item.incident_id}`}>Incident {item.incident_id.slice(0,8)}</NavLink><small className="table-subtext">Original {item.original_transfer_id}</small></td><td><b>{formatMoney(item.amount,item.currency)}</b></td><td><StatusPill tone={tone}>{status}</StatusPill>{item.operation_status&&<small className="table-subtext">Operation {item.operation_status}</small>}</td><td>{item.requested_by||'Unknown'}</td><td>{item.approved_by||'—'}{item.approved_at&&<small className="table-subtext">{new Date(item.approved_at).toLocaleString()}</small>}</td><td>{item.policy_version===null?'Unavailable':`v${item.policy_version}`}</td><td>{new Date(item.expires_at).toLocaleString()}</td></tr>})}</tbody></table></div>:<div className="empty-state page-empty"><div className="empty-icon"><ShieldCheck size={18}/></div><b>No persisted approval records</b><p>There are no saved action-bound approvals to review. Creating or approving a live recovery is disabled in this build.</p></div>}
    </section>
  </>
}
function Audit(){const {data=[],isLoading,error}=useQuery({queryKey:['audit'],queryFn:()=>api<any[]>('/audit')});return <><PageHead kicker="GOVERNANCE" title="Audit trail" description="A traceable record of incident decisions and financial operations."/><div className="panel audit-panel">{isLoading?'Loading audit history…':error?<div className="error-text">{String(error)}</div>:data.length?<div className="audit-list">{data.map((event:any,index:number)=><div className="audit-item" key={`${event.timestamp}-${index}`}><div className="audit-dot"><Clock3 size={13}/></div><div className="audit-body"><b>{event.event_type.replaceAll('_',' ').toLowerCase()}</b><p>{event.incident_id?`Incident ${event.incident_id.slice(0,8)}`:'Workspace event'} · {event.external_transfer_id||'No external transfer verified'}</p><small>{new Date(event.timestamp).toLocaleString()} · {event.actor}{event.policy_version?` · Policy v${event.policy_version}`:''}{event.approval_reference?` · Approval ${event.approval_reference}`:''}</small></div><StatusPill>{event.new_state||'recorded'}</StatusPill></div>)}</div>:<div className="empty-state"><div className="empty-icon"><FileClock size={18}/></div><b>No audit events yet</b><p>Actions and policy decisions will be recorded here.</p></div>}</div></>}
function TreasurySettings(){
  const query=useQuery<any[]>({queryKey:['treasury-policies'],queryFn:()=>api<any[]>('/treasury/policies')})
  const [form,setForm]=useState({currency:'USD',reserve_floor:'',approval_threshold:'',priority_order:'CRITICAL,HIGH,NORMAL,LOW'})
  const [busy,setBusy]=useState(false)
  const [message,setMessage]=useState('')
  const [error,setError]=useState('')
  async function save(e:FormEvent){
    e.preventDefault();setBusy(true);setMessage('');setError('')
    try{
      const priority_order=form.priority_order.split(',').map(value=>value.trim().toUpperCase())
      await api(`/treasury/policies/${form.currency.toUpperCase()}`,{method:'PUT',body:JSON.stringify({reserve_floor:form.reserve_floor,approval_threshold:form.approval_threshold,priority_order})})
      setMessage(`${form.currency.toUpperCase()} reserve policy saved and audited.`)
      await query.refetch()
    }catch(err){setError(err instanceof Error?err.message:'Could not save reserve policy')}
    finally{setBusy(false)}
  }
  return <><PageHead kicker="WORKSPACE GOVERNANCE" title="Treasury policies" description="Configure per-currency reserve floors, approval thresholds, and obligation priority order."/><div className="settings-grid"><section className="panel settings-form-panel"><div className="eyebrow">POLICY EDITOR</div><h2>Reserve and approval rules</h2><p className="muted small-text">Each save increments the policy version and creates an audit event. A configured policy does not authorize a payment.</p><form onSubmit={save}><label>Currency<select value={form.currency} onChange={e=>setForm({...form,currency:e.target.value})}><option>USD</option><option>EUR</option><option>GBP</option><option>SGD</option><option>AUD</option></select></label><div className="form-row"><label>Reserve floor<input required type="number" min="0" step="0.0001" value={form.reserve_floor} onChange={e=>setForm({...form,reserve_floor:e.target.value})}/></label><label>Approval threshold<input required type="number" min="0" step="0.0001" value={form.approval_threshold} onChange={e=>setForm({...form,approval_threshold:e.target.value})}/></label></div><label>Priority order<input required value={form.priority_order} onChange={e=>setForm({...form,priority_order:e.target.value})}/></label><small className="table-subtext">Enter each once, separated by commas: CRITICAL,HIGH,NORMAL,LOW</small>{message&&<p className="success-text" role="status">{message}</p>}{error&&<p className="error-text" role="alert">{error}</p>}<button className="primary" disabled={busy}>{busy?'Saving…':'Save policy'} <ChevronRight size={15}/></button></form></section><section className="panel settings-policies"><div className="eyebrow">SAVED POLICIES</div><h2>Configured currencies</h2>{query.isPending?<p>Loading policies…</p>:query.error?<p className="error-text">{String(query.error)}</p>:query.data?.length?query.data.map(policy=><article className="saved-policy" key={policy.currency}><div><b>{policy.currency} · version {policy.version}</b><p>Reserve {policy.currency} {groupedDecimal(String(policy.reserve_floor))} · approval threshold {policy.currency} {groupedDecimal(String(policy.approval_threshold))}</p><small>{policy.priority_order.join(' → ')} · updated {new Date(policy.updated_at).toLocaleString()}</small></div><button className="secondary small" onClick={()=>setForm({currency:policy.currency,reserve_floor:String(policy.reserve_floor),approval_threshold:String(policy.approval_threshold),priority_order:policy.priority_order.join(',')})}>Edit</button></article>):<div className="empty-state"><b>No treasury policies configured</b><p>Policies are required before a live balance can be evaluated against reserve rules.</p></div>}</section></div><div className="alert-banner warning-banner"><div className="alert-glyph"><ShieldCheck size={17}/></div><div><b>Role-separated policy access</b><p>Production requires a distinct admin token to change policies. This prototype uses shared bearer tokens, not named user identities or organization SSO. Local development allows the operator token to edit policies.</p></div></div></>}
export default App
